 IF p_origin IS NULL OR p_origin!~'^http://(localhost|127\.0\.0\.1)(:[0-9]{2,5})?$' OR p_now IS NULL THEN RAISE EXCEPTION 'Use the local CMS address.' USING ERRCODE='CMS04';END IF;
